/**
 * Feeds the panel and the row view a payload generated by the real backend: the metrics are the
 * output of `remediation_scoring.score_remediation` (with a stub detector and a declared extra
 * field) and the rows are filtered through the key whitelist of `evaluation_service`'s
 * `predictions_preview`. Regenerate the fixture when either side changes shape.
 */
import { render, screen, within } from '@testing-library/react';
import { describe, expect, it } from 'vitest';

import fixture from './remediationBackendShape.fixture.json';
import RemediationMetricsPanel, { RemediationRowView, type RemediationMetrics, type RemediationRow } from './RemediationMetricsPanel';

const METRICS = fixture.metrics as unknown as RemediationMetrics;
const ROWS = fixture.predictions_preview as unknown as RemediationRow[];

describe('remediation components against the backend payload shape', () => {
    it('the metrics panel reads extra_fields and the overall resolved rate', () => {
        render(<RemediationMetricsPanel metrics={METRICS} provenance="Run #1" />);
        expect(screen.getByTestId('rem-pass')).toHaveTextContent('33.3%');
        expect(screen.getByTestId('rem-resolved')).toHaveTextContent('66.7%');
        const fields = screen.getByTestId('rem-fields');
        expect(within(fields).getByText('severity')).toBeInTheDocument();
        expect(fields).toHaveTextContent('33.3%');
    });

    it('the row view reads row_finding and row_passage_headers', () => {
        render(<RemediationRowView row={ROWS[0]} />);
        expect(screen.getByTestId('remediation-row-finding')).toHaveTextContent('injection.query');
        expect(screen.getByTestId('remediation-row-finding')).toHaveTextContent('lines 11');
        expect(screen.getByTestId('rem-passage-P1')).toHaveTextContent('[P1]');
        expect(screen.getByTestId('rem-passage-P1')).toHaveTextContent('(cited)');
        expect(screen.getByTestId('rem-passage-P2')).toHaveTextContent('lib/db.py:3-4 (run)');
        expect(screen.getByTestId('rem-chip-resolved')).toHaveTextContent('finding resolved');
        expect(screen.getByTestId('rem-diff')).toBeInTheDocument();
    });

    it('a malformed backend row renders as malformed with its reason chips', () => {
        render(<RemediationRowView row={ROWS[2]} />);
        expect(screen.getByTestId('remediation-row-malformed')).toBeInTheDocument();
        expect(screen.getByTestId('rem-chip-applies')).toHaveTextContent('patch does not apply');
    });
});
